let left = amount;
const items = [];
const mktBuyCount = { '沪': 0, '深': 0 };
// 沪深各 1 只优先：仅当两个市场都有候选时，把每市场上限设为 ceil(maxBuys/2)
const hasSh = cands.some(r => r.mkt === '沪'), hasSz = cands.some(r => r.mkt === '深');
const perMktCap = (hasSh && hasSz && maxBuys >= 2) ? Math.ceil(maxBuys / 2) : Infinity;

/* ===== 资金池分配（修复「排序第一吸干全部资金」）=====
 * 旧逻辑 want = min(capRoom, indRoom, mktRoom, left) —— left 是总剩余，
 * 排序第一的标的会吃满全部增量资金，导致另一市场抢不到钱，沪深配比失效。
 * 新逻辑：先按 sh_ratio 切沪深两个资金池，再在市场内按权重微积分分配。
 * 市场池剩余不足时，允许向另一市场借用「未被使用」的额度（仅当对侧无候选）。 */
const pool = { '沪': amount * shW, '深': amount * (1 - shW) };
const poolUsed = { '沪': 0, '深': 0 };
const otherMkt = m => (m === '沪' ? '深' : '沪');
cands.forEach(r => {
  if (items.length >= maxBuys) { skipped.push({ r: r, why: '本次已达 ' + maxBuys + ' 只上限（省佣金）' }); return; }
  if (mktBuyCount[r.mkt] >= perMktCap) { skipped.push({ r: r, why: r.mkt + '市本次配额已满' }); return; }
  const capRoom = r.capPct / 100 * base - r.mv;
  const indRoom = maxI / 100 * base - (indUsed[r.ind] || 0);
  const mktRoom = (r.mkt === '沪' ? shW : 1 - shW) * base - (mktUsed[r.mkt] || 0);
  // ① 本市场资金池剩余（增量口径）
  let poolLeft = pool[r.mkt] - poolUsed[r.mkt];
  // ② 若本市场已无候选可买，可借用对侧未用的池（避免现金白白闲置）
  const otherHasCandidate = cands.some(x => x.mkt === otherMkt(r.mkt) && mktBuyCount[x.mkt] < perMktCap);
  if (!otherHasCandidate) poolLeft += (pool[otherMkt(r.mkt)] - poolUsed[otherMkt(r.mkt)]);
  // ③ 按权重微积分：该股目标金额 = w% × 本次投入，但不能超过各类剩余额度
  const weightAmt = r.w / 100 * amount;
  let want = Math.min(capRoom, indRoom, mktRoom, poolLeft, weightAmt);
  // ④ 若按权重算出的金额买不起 1 手，允许用本市场剩余池补足到 1 手
  const lotCost = r.price * lot;
  if (want > 0 && want < lotCost && poolLeft >= lotCost) want = Math.min(lotCost, poolLeft, capRoom, indRoom, mktRoom);
  if (want <= 0) { skipped.push({ r: r, why: '额度已满' }); return; }
  const sh = Math.floor(want / r.price / lot) * lot;
  if (sh <= 0) { if (poolLeft >= r.price * lot) skipped.push({ r: r, why: '额度不足 1 手' }); return; }
  const cost = sh * r.price;
  const fee = Math.max(cost * (+S.settings.comm || 0), minFee) + cost * (+S.settings.trans || 0);
  // ⑤ 摩擦硬门槛：单只成交额 < min_ticket 直接不买（5 元最低佣金会吃掉收益），额度让给同市场后续标的
  if (cost < minTicket) {
    skipped.push({ r: r, why: '额度太小（' + fmt(cost, 0) + ' 元 < ' + fmt(minTicket, 0) + '），攒够再买' });
    return;
  }
  items.push({ r: r, shares: sh, cost: cost, fee: fee, lowTicket: cost < minTicket });
  left -= cost;
  poolUsed[r.mkt] += cost;
  mktBuyCount[r.mkt] = (mktBuyCount[r.mkt] || 0) + 1;
  indUsed[r.ind] = (indUsed[r.ind] || 0) + cost;
  mktUsed[r.mkt] = (mktUsed[r.mkt] || 0) + cost;
});

