// ③ 按权重微积分：目标金额 = w% × 本次投入
const weightAmt = r.w / 100 * amount;
// ④ 实际下单额：在「权重额」与「min_ticket 下限」之间取大，但不超过各类剩余额度
//    （否则小本金时按权重算出的 1200 元会被 min_ticket 直接一票否决，导致一只都买不了）
const hardCap = Math.min(capRoom, indRoom, mktRoom, poolLeft);
let want = Math.max(weightAmt, Math.min(minTicket, hardCap));
want = Math.min(want, hardCap);
const lotCost = r.price * lot;
if (want > 0 && want < lotCost && hardCap >= lotCost) want = lotCost;   // 不够 1 手→抬到 1 手
if (want <= 0) { skipped.push({ r: r, why: '额度已满' }); return; }
const sh = Math.floor(want / r.price / lot) * lot;
if (sh <= 0) { skipped.push({ r: r, why: '额度不足 1 手（' + fmt(lotCost, 0) + ' 元）' }); return; }
const cost = sh * r.price;
const fee = Math.max(cost * (+S.settings.comm || 0), minFee) + cost * (+S.settings.trans || 0);
// ⑤ 摩擦兜底：只有在「本市场池确实不够 min_ticket」时才不买，避免被 5 元最低佣金吃掉
if (cost < minTicket && hardCap < minTicket) {
  skipped.push({ r: r, why: '额度太小（' + fmt(cost, 0) + ' 元 < ' + fmt(minTicket, 0) + '），攒够再买' });
  return;
}
items.push({ r: r, shares: sh, cost: cost, fee: fee, lowTicket: cost < minTicket });

